// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        Bank bank = new Bank();
        vm.startPrank(address(bank));
        try c.airDrop() {
            vm.stopPrank();
            uint256 bal = c.tokenBalance(address(bank));
            assertTrue(bal % 20 == 0);
        } catch {
            vm.stopPrank();
            assertTrue(c.tokenBalance(address(bank)) % 20 == 0);
        }
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
